package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomStringUtils_random_TriageGen5Test {















    @Test
    public void testRandom_SurrogateLogic() {
        // We need to force the code into surrogate branches.
        // High surrogate range: 55296 - 56191
        // Low surrogate range: 56320 - 57343
        // Private high surrogate: 56192 - 56319

        // Custom Random to return specific values to trigger surrogate paths
        Random mockRandom = new Random() {
            private int callCount = 0;
            @Override
            public int nextInt(int bound) {
                callCount++;
                // Force specific characters via the math: ch = (char) (random.nextInt(gap) + start)
                // Let's use start = 55296 and gap = 1000
                if (callCount == 1) return 0;    // High surrogate (55296)
                if (callCount == 2) return 500;  // Low surrogate (56320)
                if (callCount == 3) return 900;  // Private high surrogate (56192)
                if (callCount == 4) return 1000; // Normal char
                return 0;
            }
        };

        // Testing High Surrogate Branch (inserts low surrogate before)
        // ch = 55296 + 0 = 55296
        String res1 = RandomStringUtils.random(1, 55296, 55297, false, false, null, mockRandom);
        // Because count is 1, it enters the 'if(count == 0) count++' block to avoid index out of bounds
        assertEquals(1, res1.length());

        // Testing Low Surrogate Branch (inserts high surrogate after)
        // ch = 56320 + 0 = 56320
        mockRandom = new Random() {
            private int callCount = 0;
            @Override
            public int nextInt(int bound) {
                callCount++;
                if (callCount == 1) return 0; // 56320
                return 0;
            }
        };
        String res2 = RandomStringUtils.random(2, 56320, 56321, false, false, null, mockRandom);
        assertEquals(2, res2.length());

        // Testing Private High Surrogate (skips it)
        mockRandom = new Random() {
            private int callCount = 0;
            @Override
            public int nextInt(int bound) {
                callCount++;
                if (callCount == 1) return 900; // 56192
                return 0;
            }
        };
        String res3 = RandomStringUtils.random(1, 56192, 56193, false, false, null, mockRandom);
        // It should skip the private surrogate and try again. 
        // Since our mock returns 0 for the second call (56192 + 0 = 56192), 
        // we need a mock that eventually returns a valid char to prevent infinite loop in test.

        mockRandom = new Random() {
            private int callCount = 0;
            @Override
            public int nextInt(int bound) {
                callCount++;
                if (callCount == 1) return 900; // Skip
                return 0; // Valid char (56192 + 0 = 56192 is still private... let's pick a safe one)
            }
        };
        // Redefining mock for a clean test of the "skip" logic
        mockRandom = new Random() {
            private int callCount = 0;
            @Override
            public int nextInt(int bound) {
                callCount++;
                if (callCount == 1) return 0;    // 56192 (skip)
                if (callCount == 2) return 1000; // 57192 (normal)
                return 0;
            }
        };
        String res4 = RandomStringUtils.random(1, 56192, 57193, false, false, null, mockRandom);
        assertEquals(1, res4.length());
    }


}

package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomStringUtils_random_TriageGen5Test {

















    @Test
    public void testRandom_FilterLogic() {
        // Test the 'else' branch where ch is not letter/number/neither
        // If letters=true, numbers=false, and we pick a digit, it should skip (count++)
        Random mockRandom = new Random() {
            private int callCount = 0;
            @Override
            public int nextInt(int bound) {
                callCount++;
                if (callCount == 1) return 0; // '1' (Digit)
                return 0; // 'a' (Letter)
            }
        };
        // 49 is '1'. gap = 1. start = 49.
        String result = RandomStringUtils.random(1, 49, 50, true, false, null, mockRandom);
        assertEquals(1, result.length());
    }
}
